97-// -------------------------------------------------------------------- state ---
98-/** runs in the page: one state record from the production bridges and the DOM. */
99:function pageReadState() {
100-  const w = window;
101-  const hud = document.querySelector('[data-story-guidance-hud]');
102-  const feed = document.querySelector('aside[aria-label="Current story objective"]');
103-  const caption = document.querySelector('[data-story-caption]');
104-  const qp = new URLSearchParams(location.search);
105-  const text = (el) => (el ? el.innerText.replace(/\s*\n\s*/g, ' | ').trim() : null);
106-  const out = {
107-    href: location.href,
108-    lane: qp.get('movie') === '1' ? 'movie' : 'manual',
109-    urlStory: qp.get('story'),
110-    wallMs: Math.round(performance.now()),
111-    beat: w.__storyBeat ?? null,
112-    objectiveId: hud?.getAttribute('data-objective-id') ?? null,
113-    markerLabel: hud?.getAttribute('data-objective-marker-label') ?? null,
114-    health: hud?.getAttribute('data-objective-health') ?? null,
115-    hudText: text(hud),
116-    feedText: text(feed),
117-    caption: caption ? caption.innerText.trim() : null,
118-    interactionPrompts: [...document.querySelectorAll('[data-interaction-prompt="primary"]')].map(text),
119-  };
120-  const ap = w.__autopilot;
121-  if (ap) {
122-    out.autopilot = { beat: ap.beat, clock: ap.clock, pos: ap.pos, stillTime: ap.stillTime,
123-      teleportNudgesTotal: ap.teleportNudgesTotal, routeAction: ap.routeAction ?? null };
124-  }
125-  try {
126-    const snap = w.__paravoxiaJourneyProbe?.snapshot?.();
127-    if (snap) {
128-      out.story = snap.story;
